TLM.f("Tempora/Epi3-0",{"officium":"Dominica III Post Epiphaniam","rule":["Gloria","Credo","Prefatio=Trinitate"],"sections":{"Introitus":[{"k":"ref","la":"Ps 96:7-8"},{"k":"text","la":"Adoráte Deum, omnes Angeli ejus: audívit, et lætáta est Sion: et exsultavérunt fíliæ Judæ."},{"k":"ref","la":"Ps 96:1"},{"k":"text","la":"Dóminus regnávit, exsúltet terra: læténtur ínsulæ multæ."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Adoráte Deum, omnes Angeli ejus: audívit, et lætáta est Sion: et exsultavérunt fíliæ Judæ."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, infirmitatem nostram propítius réspice: atque, ad protegéndum nos, déxteram tuæ majestátis exténde."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 12:16-21"},{"k":"text","la":"Fratres: Nolíte esse prudéntes apud vosmetípsos: nulli malum pro malo reddéntes: providéntes bona non tantum coram Deo, sed étiam coram ómnibus homínibus. Si fíeri potest, quod ex vobis est, cum ómnibus homínibus pacem habéntes: Non vosmetípsos defendéntes, caríssimi, sed date locum iræ. Scriptum est enim: Mihi vindícta: ego retríbuam, dicit Dóminus. Sed si esuríerit inimícus tuus, ciba illum: si sitit, potum da illi: hoc enim fáciens, carbónes ignis cóngeres super caput ejus. Noli vinci a malo, sed vince in bono malum."}],"Graduale":[{"k":"ref","la":"Ps 101:16-17"},{"k":"text","la":"Timébunt gentes nomen tuum, Dómine, et omnes reges terræ glóriam tuam."},{"k":"text","la":"Quóniam ædificávit Dóminus Sion, et vidébitur in majestáte sua. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 96:1"},{"k":"text","la":"Dóminus regnávit, exsúltet terra: læténtur ínsulæ multæ. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 8:1-13"},{"k":"text","la":"In illo témpore: Cum descendísset Jesus de monte, secútæ sunt eum turbæ multæ: et ecce, leprósus véniens adorábat eum, dicens: Dómine, si vis, potes me mundáre. Et exténdens Jesus manum, tétigit eum, dicens: Volo. Mundáre. Et conféstim mundáta est lepra ejus. Et ait illi Jesus: Vide, némini díxeris: sed vade, osténde te sacerdóti, et offer munus, quod præcépit Móyses, in testimónium illis. Cum autem introísset Caphárnaum, accéssit ad eum centúrio, rogans eum et dicens: Dómine, puer meus jacet in domo paralýticus, et male torquetur. Et ait illi Jesus: Ego véniam, et curábo eum. Et respóndens centúrio, ait: Dómine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanábitur puer meus. Nam et ego homo sum sub potestáte constitútus, habens sub me mílites, et dico huic: Vade, et vadit; et alii: Veni, et venit; et servo meo: Fac hoc, et facit. Audiens autem Jesus, mirátus est, et sequéntibus se dixit: Amen, dico vobis, non inveni tantam fidem in Israël. Dico autem vobis, quod multi ab Oriénte et Occidénte vénient, et recúmbent cum Abraham et Isaac et Jacob in regno cœlórum: fílii autem regni ejiciéntur in ténebras exterióres: ibi erit fletus et stridor déntium. Et dixit Jesus centurióni: Vade et, sicut credidísti, fiat tibi. Et sanátus est puer in illa hora."}],"Offertorium":[{"k":"ref","la":"Ps 117:16; 117:17"},{"k":"text","la":"Déxtera Dómini fecit virtutem, déxtera Dómini exaltávit me: non móriar, sed vivam, et narrábo ópera Dómini."}],"Secreta":[{"k":"text","la":"Hæc hóstia, Dómine, quǽsumus, emúndet nostra delícta: et, ad sacrifícium celebrándum, subditórum tibi córpora mentésque sanctíficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 4:22"},{"k":"text","la":"Mirabántur omnes de his, quæ procedébant de ore Dei."}],"Postcommunio":[{"k":"text","la":"Quos tantis, Dómine, largíris uti mystériis: quǽsumus; ut efféctibus nos eórum veráciter aptáre dignéris."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5e22ba60d4b44e32":{"t":"Ps 96, 7-8, Ps 96, 1\n(Ps 96, 7-8) Klanjajte se Bogu svi anđeli njegovi! Čuje Sion i raduje se, veselo pjevaju sve Judine kćeri. (Ps 96, 1) Gospodin kraljuje, neka kliče zemlja, neka se raduju mnogi otoci.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 96, 7-8) Klanjajte se Bogu svi anđeli njegovi! Čuje Sion i raduje se, veselo pjevaju sve Judine kćeri."},"e2ae07777a51ab3b":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, milostivo pogledaj na našu slabost i pruži desnicu svojega veličanstva da nas zaštitiš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"b318a1049d40aad5":{"t":"Rim 12, 16-21\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Ne smatrajte sami sebe mudrima, ne vraćajte nikome zla za zlo, nastojte oko dobra ne samo pred Bogom nego i pred svim ljudima. Ako je moguće i koliko je do vas, budite u miru sa svima. Ne osvećujte se, predragi, nego prepustite to Božjoj srdžbi, kao što je pisano: »Moja je osveta, ja ću uzvratiti«, kaže Gospodin. Naprotiv, ako je tvoj neprijatelj gladan, nahrani ga, ako je žedan napoji ga. Čineći tako skupit ćeš žeravicu na njegovu glavu. Ne daj se nadvladati od zla, nego zlo svladaj dobrom."},"30e75e455763b37f":{"t":"Ps 101, 16-17\nBojat će se narodi imena tvojega, Gospodine, i tvoje slave svi kraljevi zemlje. Jer je Gospodin sagradio Sion i objavit će se u svojem veličanstvu.\n\nPs 96, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodin kraljuje, neka kliče zemlja, neka se raduju mnogi otoci. <i>Aleluja</i>."},"4755f434b0add207":{"t":"Mt 8, 1-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: kad je Isus sišao s gore, išlo je za njim mnogo naroda. I gle, pristupi gubavac koji mu se pokloni i reče: Gospodine, ako hoćeš, možeš me očistiti. Isus pruži ruku, dotakne ga i reče Hoću. Budi čist. I odmah se očisti od svoje gube. Tada mu Isus reče: Pazi, ne kazuj nikome, nego pođi, pokaži se svećeniku i prinesi dar njima za svjedočanstvo, kako je naredio Mojsije. Kad je Isus ušao u Kafarnaum pristupi k njemu stotnik, zamoli ga i reče: Gospodine, moj sluga leži kod kuće uzet i teško se muči. Isus mu reče: Ja ću doći i izliječit ću ga. A stotnik odgovori: Gospodine, nisam dostojan da uđeš pod krov moj, nego samo reci riječ i ozdravit će moj sluga. I ja sam čovjek pod vlašću i imam pod sobom vojnike, pa kažem jednomu: Idi, – i on ide, i drugome: Dođi, – i on dođe, a svojem sluzi: Učini to, – i on učini. Kad je Isus to čuo, zadivi se i reče pratiocima: Zaista vam kažem u Izraelu nisam našao tolike vjere. Kažem vam da će doći mnogi s istoka i sa zapada i sjest će s Abrahamom, Izakom i Jakovom za stol u nebeskom kraljevstvu, a sinovi će kraljevstva biti izbačeni napolje u tamu, gdje će biti plač i škripa zubi. A stotniku reče: Idi i neka ti bude kako si vjerovao. I u taj čas ozdravi sluga."},"a63cb5f96fa870c3":{"t":"Ps 117, 16-17\nDesnica Gospodnja učini čudo, desnica me Gospodnja podiže! Neću umrijeti nego živjeti i naviještati djela Gospodnja."},"fbb53f48d9c24f02":{"t":"Molimo, Gospodine, da ovaj žrtveni dar izbriše naša zlodjela te da dušu i tijelo tvojih podložnika posveti za svetkovanje žrtve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:"},"d63bef8a01a22821":{"t":"Lk 4, 22\nSvi su se divili riječima koje su izlazile iz Božjih usta."},"f2d0892ba07a1752":{"t":"<i>Pomolimo se</i>.\nNama, Gospodine, kojima daješ tolika otajstva, udostoj se dati i to da doista dostojno primamo njihove učinke.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
